'use strict';
const TOPIC=window.LEARNING_TOPIC||{};
const STORAGE_KEY=TOPIC.storageKey||'samfunnsverksted-konflikt-v1';
const main=document.querySelector('#main');
const dialog=document.querySelector('#notes-dialog');
const blankState=()=>({level:'easy',theme:'light',answers:{},quiz:{},quizVersion:QUIZ_VERSION,wordNotes:{},checks:{},finalTopic:TOPIC.finalTopics?.[0]||'Første verdenskrig'});
let state=blankState(),storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(saved&&typeof saved==='object')state=LearningState.migrate({...state,...saved,answers:saved.answers||{},quiz:saved.quiz||{},wordNotes:saved.wordNotes||{},checks:saved.checks||{},quizVersion:saved.quizVersion||1},QUIZ_VERSION);}catch{storageAvailable=false;}
if(!['easy','normal'].includes(state.level))state.level='easy';
let current='start',toastTimer;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const easy=()=>state.level==='easy';
const external=(s,label)=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(label||s.title)} ↗</a>`;
const APPROVED_IMAGES={
 mellomkrig:{src:'assets/arbeidsledighet-1931.webp',title:'Når arbeidet forsvinner',period:'Tyskland · 1931',alt:'KI-rekonstruksjon av et par ved et kjøkkenbord i Tyskland i 1931. Mannen leser et brev, og noen få mynter ligger på bordet.',easy:'En familie prøver å få pengene til å strekke til. Motivet viser en tenkt situasjon med arbeidsledighet og utrygghet under den økonomiske krisen.',normal:'En tenkt arbeidstaker og partneren hans undersøker et brev ved kjøkkenbordet. De få myntene og det enkle hjemmet brukes til å illustrere økonomisk utrygghet. Bildet forteller ikke hva menneskene mente politisk.',question:'Hvordan kan arbeidsledighet påvirke et menneske og en familie? Hvorfor er økonomisk krise alene ikke en full forklaring på diktatur?'},
 kaldkrig:{src:'assets/berlin-1989.webp',title:'Mennesker møtes igjen',period:'Berlin · November 1989',alt:'KI-rekonstruksjon av mennesker som møtes ved en åpnet grenseovergang i Berlin i 1989. To mennesker omfavner hverandre, og en bom står åpen.',easy:'To mennesker omfavner hverandre ved en åpen grenseovergang. Andre går forbi. Deler av muren står fortsatt. Motivet viser glede og større bevegelsesfrihet.',normal:'En tenkt gjenforening ved en åpnet grenseovergang illustrerer hvordan politiske endringer kunne få betydning for hverdagsliv, relasjoner og bevegelsesfrihet. Bildet viser at åpningen av grensen og den fysiske fjerningen av muren var ulike prosesser.',question:'Sammenlign med Berlin-bildet fra 1961 i neste kapittel. Hva har endret seg for menneskene, og hva står fortsatt igjen?'},
 cuba:{src:'assets/cubakrisen-flyfoto-1962.webp',title:'Hva kan et flyfoto fortelle?',period:'Cubakrisen · Oktober 1962',alt:'KI-rekonstruksjon av to amerikanske fototolkere som undersøker flyfoto med et forstørrelsesglass på et lysbord.',easy:'To fototolkere undersøker bilder tatt fra luften. Bildet illustrerer hvordan mennesker må lete etter detaljer, sammenligne og tolke informasjon.',normal:'Flyfoto var viktig dokumentasjon under Cubakrisen. Denne tenkte arbeidssituasjonen viser at bilder må undersøkes og tolkes før de kan inngå i en begrunnelse. Selve illustrasjonen dokumenterer ikke analysene som faktisk ble gjort.',question:'Hva er forskjellen på å se noe i et bilde og å tolke hva det betyr? Hvilke andre opplysninger ville du trenge?',note:'Flyfotoene inne i denne illustrasjonen er også oppdiktet.',sourceUrl:'https://www.archives.gov/milestone-documents/aerial-photograph-of-missiles-in-cuba',sourceTitle:'Se et faktisk flyfoto fra 1962 hos National Archives'},
 ww1:{kind:'archive',src:'assets/somme-1916-arkiv.webp',width:1400,height:1069,title:'På vakt i skyttergraven',period:'Somme, Frankrike · Juli 1916',alt:'Svart-hvitt-fotografi av britiske soldater i en skyttergrav ved Somme. En soldat står på vakt ved kanten, mens andre hviler nede i graven.',easy:'Britiske soldater er i en tysk skyttergrav de har tatt. En soldat står på vakt. Andre hviler. Bildet viser et øyeblikk under slaget ved Somme.',normal:'Soldater fra 11. bataljon i Cheshire Regiment har tatt en tysk skyttergrav ved Ovillers-la-Boisselle. Én holder vakt mens andre hviler. Fotografiet viser et avgrenset øyeblikk, ikke hele soldatenes hverdag eller slaget ved Somme.',question:'Hva viser bildet om soldatenes hverdag? Hva kan bildet ikke fortelle oss?',credit:'Fotograf: John Warwick Brooke. Imperial War Museums, Q 3990.',license:'Public domain – opphavsretten er utløpt',licenseUrl:'https://commons.wikimedia.org/wiki/File:Cheshire_Regiment_trench_Somme_1916.jpg#Summary',note:'WebP-kopi med samme utsnitt som kildefilen. Kilden opplyser at kontrast og skarphet i skanningen er justert.',sourceUrl:'https://commons.wikimedia.org/wiki/File:Cheshire_Regiment_trench_Somme_1916.jpg',sourceTitle:'Se bildeopplysninger og bruksvilkår hos Wikimedia Commons',archiveUrl:'https://www.iwm.org.uk/collections/item/object/205193132',archiveTitle:'Se katalogposten hos Imperial War Museums'},
 ww2:{src:'assets/rasjoneringsko-1942.webp',title:'I matkø under okkupasjonen',period:'Norge · Høsten 1942',alt:'KI-rekonstruksjon av en matkø utenfor en norsk butikk. En kvinne holder et rasjoneringskort. Tyske soldater går i bakgrunnen.',easy:'Mennesker venter utenfor en butikk. Kvinnen foran holder et rasjoneringskort og en handlekurv. Soldatene i bakgrunnen viser okkupasjonsmakten.',normal:'Rasjoneringskortet, køen og det nesten tomme butikkvinduet viser hvordan varemangel kunne prege siviles hverdag. Den militære tilstedeværelsen er synlig i bakgrunnen.',question:'Hvordan kan krig forandre hverdagen, også der det ikke foregår kamper?'},
 kriser:{kind:'archive',src:'assets/berlin-mauerbau-1961-arkiv.webp',width:797,height:541,title:'Muren blir bygd',period:'Berlin · August 1961',alt:'Svart-hvitt-fotografi av arbeidere som setter opp betongblokker med en kran bak piggtråd under byggingen av Berlinmuren.',easy:'Arbeidere setter opp store blokker av betong. Foran dem ligger piggtråd. Bildet viser byggingen av Berlinmuren i august 1961.',normal:'Betongblokker settes opp med en kran bak piggtråd under byggingen av Berlinmuren. Fotografiet dokumenterer selve grenseanlegget, men forklarer ikke alene myndighetenes formål eller menneskenes erfaringer.',question:'DDR kalte muren et vern mot fascisme. Hvordan kan vi bruke bildet til å undersøke denne påstanden? Hva trenger vi andre kilder til?',credit:'Bundesarchiv, Bild 173-1321 / Helmut J. Wolf / CC-BY-SA 3.0.',license:'CC BY-SA 3.0 DE',licenseUrl:'https://creativecommons.org/licenses/by-sa/3.0/de/deed.en',note:'WebP-kopi uten ytterligere beskjæring. Rammen er fjernet i kildefilen fra Wikimedia Commons.',sourceUrl:'https://commons.wikimedia.org/wiki/File:Bundesarchiv_Bild_173-1321,_Berlin,_Mauerbau.jpg',sourceTitle:'Se bildeopplysninger og kilde hos Wikimedia Commons'},
 cubaArchive:{kind:'archive',src:'assets/cuba-flyfoto-1962-arkiv.webp',width:690,height:576,title:'Flyfotoet fra Cuba',period:'San Cristóbal, Cuba · Foto tatt 14. oktober 1962',alt:'Svart-hvitt-flyfoto av et rakettanlegg ved San Cristóbal på Cuba. Påførte engelske etiketter og piler peker på utstyr, raketthengere og teltområder.',easy:'Et amerikansk fly tok dette bildet av Cuba. Piler og tekst peker på utstyr på bakken. Disse merkene viser hvordan bildet ble tolket.',normal:'Flyfoto av et sovjetisk rakettanlegg ved San Cristóbal. Amerikanske markeringer peker ut blant annet utskytingsutstyr og raketthengere. Vi må skille mellom det fotografiet viser, og forklaringene som er lagt på bildet.',question:'Hva ser du selv? Hva trenger du pilene og forklaringene for å forstå?',credit:'USAs forsvarsdepartement / John F. Kennedy Library, National Archives. PX1966-020-007, NAID 193926. Enkeltfotograf er ikke oppgitt i kilden.',license:'Public domain – ingen kjente opphavsrettslige begrensninger',licenseUrl:'https://docsteach.org/document/mrbm-field-launch-site-san-cristobal-no-1/',note:'WebP-kopi uten beskjæring. Piler og tekst er del av arkivdokumentet; de er ikke lagt til av dette nettstedet.',sourceUrl:'https://www.archives.gov/milestone-documents/aerial-photograph-of-missiles-in-cuba',sourceTitle:'Se fotografiet og arkivopplysningene hos National Archives'}
};
function historicalImage(id){const im=TOPIC.images?.[id]||APPROVED_IMAGES[id];if(!im)return '';const archive=im.kind==='archive',width=im.width||1536,height=im.height||1024;return `<figure class="historical-figure" data-image="${esc(id)}"><img src="${im.src}" srcset="${im.src.replace('.webp','-640.webp')} 640w, ${im.src} ${width}w" sizes="(max-width: 900px) calc(100vw - 40px), 680px" alt="${esc(im.alt)}" width="${width}" height="${height}" decoding="async"><figcaption><span class="image-label">${archive?esc(im.label||'ARKIVFOTO'):'KI-REKONSTRUKSJON'}</span><span class="image-period">${esc(im.period)}</span><h2>${esc(im.title)}</h2><p>${esc(easy()?im.easy:im.normal)}</p><p class="image-question"><strong>Se og snakk sammen</strong>${esc(easy()?(im.questionEasy||im.question):im.question)}</p>${archive?`<small>${esc(im.credit)}<br>Bruksvilkår: ${external({url:im.licenseUrl,title:im.license})}<br>${esc(im.note)}</small><p class="fine">${external({url:im.src,title:'Åpne bildet større'})}</p>`:`<small>Dette er en KI-generert illustrasjon av en tenkt situasjon, ikke et historisk fotografi. Personene er oppdiktet.${im.note?' '+esc(im.note):''}</small>`}${im.sourceUrl?`<p class="fine">${external({url:im.sourceUrl,title:im.sourceTitle})}${im.archiveUrl?`<br>${external({url:im.archiveUrl,title:im.archiveTitle})}`:''}</p>`:''}</figcaption></figure>`;}
function imagePreview(id){const im=APPROVED_IMAGES[id];return `<div class="card-photo"><img src="${im.src.replace('.webp','-640.webp')}" alt="${esc(im.alt)}" width="${im.width||1536}" height="${im.height||1024}" loading="lazy" decoding="async"><span>${im.kind==='archive'?'Arkivfoto':'KI-rekonstruksjon'} · ${esc(im.period)}</span></div>`;}
function imageComparison(){return `<div class="image-comparison">${historicalImage('cuba')}${historicalImage('cubaArchive')}</div>`;}
function toast(text){document.querySelector('#toast').textContent=text;document.querySelector('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.querySelector('#toast').classList.remove('visible'),4000);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{if(storageAvailable)toast('Nettleseren kan ikke lagre. Last ned svarene før du lukker siden.');storageAvailable=false;return false;}}
function getQuiz(id){return QUIZ_BANK[id]||[];}
function completed(id){return questionSummary(id).reviewed;}
function questionSummary(id){return LearningState.summary(getQuiz(id).map((_,i)=>state.quiz[`${id}-${i}`]));}
function learningIds(){return ['ord',...LESSONS.map(x=>x.id)];}
function updateHeader(){
 const ids=learningIds(),done=ids.filter(completed).length;
 document.querySelector('#progress-label').textContent=`${done} av ${ids.length} gjennomgått`;
 document.querySelector('#progress-bar').style.width=`${done/ids.length*100}%`;
 document.querySelectorAll('[data-level]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.level===state.level)));
 document.body.classList.toggle('dark',state.theme==='dark');
 document.querySelector('#theme').textContent=state.theme==='dark'?'☀':'☾';
 document.querySelector('#theme').setAttribute('aria-label',state.theme==='dark'?'Bytt til lys bakgrunn':'Bytt til mørk bakgrunn');
 document.querySelector('#station-nav').innerHTML=STATIONS.map((x,i)=>`<a href="#${x.id}" ${x.id===current?'aria-current="page"':''} class="${completed(x.id)?'done':''}"><span class="nav-number">${completed(x.id)?'✓':x.id==='start'?'→':x.id==='vis'?'↗':i}</span>${esc(x.nav)}</a>`).join('');
}
function go(){const requested=decodeURIComponent(location.hash.slice(1)||'start');current=STATIONS.some(x=>x.id===requested)||requested==='laerer'?requested:'start';stopSpeech();render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});document.querySelector('.station-nav [aria-current]')?.scrollIntoView({block:'nearest',inline:'nearest'});window.scrollTo({top:0,behavior:'instant'});}
function render(){updateHeader();if(TOPIC.renderers?.[current])TOPIC.renderers[current]();else if(current==='start')renderHome();else if(current==='ord')renderWords();else if(current==='vis')renderFinal();else if(current==='laerer')renderTeacher();else renderLesson(LESSONS.find(x=>x.id===current));restoreNotes();document.title=`${current==='start'?(TOPIC.title||'Konflikt og fred'):current==='laerer'?'For læreren':STATIONS.find(x=>x.id===current)?.title||STATIONS.find(x=>x.id===current)?.nav} · Forstå verden`;}
function renderHome(){main.innerHTML=`<section class="hero"><div><span class="eyebrow">SAMFUNNSFAG · FOV MODUL 4 · KONFLIKT OG FRED</span><h1>Hvorfor blir det krig?<em>Hvordan skaper vi fred?</em></h1><p>${easy()?'To verdenskriger. En delt verden. Mennesker som tok valg. Utforsk historien, undersøk kildene og forklar sammenhengene.':'Utforsk verdenskrigene og den kalde krigen. Undersøk hvordan makt, ideologi og menneskers valg kan skape konflikt – og muligheter for fred.'}</p><a class="primary" href="#ord">Start utforskingen <span>→</span></a><p class="fine">${learningIds().length} fagstasjoner · Din egen fart · To språkveier</p></div><div class="timeline-art"><div class="art-top"><span>ET ÅRHUNDRE MED STORE VALG</span><span class="art-tag">1914–i dag</span></div><h2>Historien henger sammen.<br>Utforsk et vendepunkt.</h2><div class="mini-line">${['1914','1939','1945'].map(year=>EVENTS.findIndex(e=>e.year===year)).map((idx,i)=>`<button class="year-button" data-event="${idx}" aria-pressed="${i===0}"><b aria-hidden="true"></b>${EVENTS[idx].year}</button>`).join('')}</div><div class="mini-line">${['1961','1989','2022'].map(year=>EVENTS.findIndex(e=>e.year===year)).map(idx=>`<button class="year-button" data-event="${idx}" aria-pressed="false"><b aria-hidden="true"></b>${EVENTS[idx].year}</button>`).join('')}</div><div class="event-box" id="hero-event" aria-live="polite"><strong>${EVENTS[0].title}</strong><p>${EVENTS[0].text}</p></div><div class="art-bottom"><strong>Årsak. Valg. Konsekvens.</strong><span>Trykk på et årstall ↗</span></div></div></section>
<section><div class="section-heading"><h2>Tre perioder. Én sammenheng.</h2><span class="fine">Les → undersøk → forklar</span></div><div class="cards"><a class="card" href="#ww1">${imagePreview('ww1')}<span class="card-number">01</span><h3>En verden i krig</h3><p>Hvorfor ble en krise til verdenskrig? Undersøk årsaker og følgene av freden.</p><small>FØRSTE VERDENSKRIG · 1914–1918 ↗</small></a><a class="card" href="#mellomkrig">${imagePreview('mellomkrig')}<span class="card-number">02</span><h3>Demokratiet under press</h3><p>Fra en vanskelig fred til diktatur, ny verdenskrig og holocaust.</p><small>MELLOMKRIGSTID OG VERDENSKRIG ↗</small></a><a class="card" href="#kaldkrig">${imagePreview('kaldkrig')}<span class="card-number">03</span><h3>En delt verden</h3><p>Supermakter, atomvåpen og mennesker midt i konflikten. Hvordan unngå ny krig?</p><small>DEN KALDE KRIGEN · CA. 1945–1991 ↗</small></a></div></section>
<p><a class="secondary" href="#idag">Fra historien til konflikter i vår tid →</a></p><section><span class="eyebrow">VELG DIN VEI</span><h2>Samme historie. Ulik språkstøtte.</h2><div class="route-picks"><button class="route-pick" data-level="easy" aria-pressed="${easy()}"><strong>Lett vei ${easy()?'✓':''}</strong><span>Kortere setninger og mer støtte.</span></button><button class="route-pick" data-level="normal" aria-pressed="${!easy()}"><strong>Vanlig vei ${!easy()?'✓':''}</strong><span>Mer sammenheng og flere nyanser.</span></button></div><div class="steps"><p><b>LES</b>Lær ordene og hovedtrekkene.</p><p><b>UNDERSØK</b>Utforsk tidslinjer, valg og kilder.</p><p><b>FORKLAR</b>Øv, snakk sammen og skriv med egne ord.</p></div></section>
<section class="goals"><span class="eyebrow">DETTE SKAL DU LÆRE</span><h2>Jeg kan …</h2><ul><li>forklare årsaker til og konsekvenser av historiske konflikter.</li><li>bruke fagord og plassere hendelser i tid.</li><li>undersøke ideologier, propaganda og ulike perspektiver.</li><li>forklare hva holocaust var og drøfte forebygging.</li><li>bruke kilder kritisk og begrunne mine forklaringer.</li></ul></section><p class="fine">Tre besvarte kontrollspørsmål markerer en fagstasjon som gjennomgått. Du ser hva du svarte riktig på første forsøk, og hva du rettet senere. Dette er øving, ikke en karakter. Skriftlige og muntlige forklaringer viser mer av hva du kan. Svar og framgang lagres bare i denne nettleseren. Du kan laste ned svarene i «Mine svar».</p>`;}
function pageHeading(label,title,intro,read=true){return `<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p class="lead">${intro}</p></div>${read?'<div class="read-controls"><button class="secondary" id="speak">▷ Les opp</button><button class="secondary" id="stop-speech" hidden>Stopp</button></div>':''}</div>`;}
function wordNotes(words){return `<aside class="side-note"><h3>Ord som hjelper</h3>${words.map(w=>{const row=WORDS.find(x=>x[0]===w);return row?`<p><strong>${esc(row[0])}</strong><br>${esc(row[1])}</p>`:'';}).join('')}<a href="#ord">Se hele ordbanken →</a></aside>`;}
function sourceLinks(keys){return `<div class="sources-inline">Faglig grunnlag: ${keys.map(k=>external(SOURCES[k])).join(' ')}<br>Tekstene på siden er pedagogiske bearbeidinger. Kildenes språk og vanskelighetsgrad varierer.</div>`;}
function writing(id,task,frame,model){return `<section class="writing"><span class="label">SNAKK SAMMEN · SKRIV SELV</span><label for="answer-${id}">${esc(task)}</label><p class="fine">Forklar gjerne muntlig først. Du kan bruke andre språk til å tenke og planlegge.</p><details ${easy()?'open':''}><summary>Hjelp til å begynne</summary><p>${esc(frame)}</p></details><textarea id="answer-${id}" data-answer="${id}" aria-describedby="save-${id}" placeholder="Skriv din forklaring her …"></textarea><span class="save-status" id="save-${id}">${storageAvailable?'Lagres automatisk i denne nettleseren.':'Lagring er ikke tilgjengelig. Last ned svarene før du lukker siden.'}</span><details><summary>Se et eksempel etter at du har prøvd</summary><p>${esc(model)}</p><p class="fine">Dette er ett mulig svar. Din begrunnelse og bruk av eksempler er viktigere enn lik ordlyd.</p></details></section>`;}
function renderLesson(lesson){const index=STATIONS.findIndex(x=>x.id===lesson.id);main.innerHTML=`${pageHeading(`STASJON ${index} · ${easy()?'LETT VEI':'VANLIG VEI'}`,lesson.title,lesson.intro)}${historicalImage(lesson.id)}<section><span class="label">01 · LES OG FORSTÅ</span><div class="reading-grid"><div class="reading" id="reading-text">${lesson[easy()?'easy':'normal'].map(p=>`<p>${p}</p>`).join('')}</div>${wordNotes(lesson.words)}</div><p class="callout">${lesson.note}</p>${sourceLinks(lesson.sources)}</section><section class="work-section"><span class="label">02 · UNDERSØK SAMMENHENGENE</span>${activity(lesson.activity)}${lesson.id==='kriser'?historicalImage('cuba'):''}</section><section class="work-section"><span class="label">03 · ØV OG FORKLAR</span><h2>Sjekk forståelsen</h2><p class="fine">Første svar blir registrert. Etterpå kan du lese, få hjelp og prøve igjen.</p>${quizMarkup(lesson.id,getQuiz(lesson.id))}${writing(lesson.id,easy()?(lesson.taskEasy||lesson.task):lesson.task,lesson.frame,lesson.model)}</section>${nextMarkup(lesson.id)}`;if(lesson.activity==='sequence')renderSequence();}
function quizMarkup(id,quiz){
 const lang=state.level;
 return `<div class="quiz" data-quiz="${id}">${quiz.map((q,i)=>{const r=state.quiz[`${id}-${i}`];return `<fieldset class="question" id="question-${id}-${i}"><legend>${i+1}. ${esc(q.stem[lang])}</legend>${q.options.map((opt,j)=>`<label><input type="radio" name="q-${id}-${i}" value="${j}" ${r?.selected===j?'checked':''} ${r?.correct?'disabled':''}>${esc(opt.text[lang])}</label>`).join('')}<button class="secondary" data-check="${id}" data-index="${i}" ${r?.correct?'disabled':''}>${r?.correct?'Riktig ✓':'Sjekk svaret'}</button><span class="feedback ${r?.correct?'correct':r?.attempts?'wrong':''}" role="status">${questionFeedback(q,r)}</span><small class="attempt-status">${r?.attempts?`Første svar: ${r.firstCorrect?'riktig':'ikke riktig'}. Antall forsøk: ${r.attempts}.`:''}</small></fieldset>`;}).join('')}<div class="quiz-summary" id="quiz-summary-${id}">${quizSummary(id)}</div></div>`;
}
function questionFeedback(q,r){if(!r?.attempts)return '';const text=r.correct?q.explanation[state.level]:q.options[r.selected].feedback[state.level];return `${r.correct?'Riktig.':'Tenk videre.'} ${esc(text)}`;}
function quizSummary(id){const x=questionSummary(id);if(!x.attempted)return 'Ingen svar ennå. Første svar blir registrert. Du kan deretter lese, få hjelp og prøve igjen.';return `${x.attempted} av ${x.total} besvart. Første svar: ${x.firstCorrect} av ${x.attempted} riktige. Riktige nå: ${x.correct} av ${x.total}.${x.corrected?` ${x.corrected} rettet etter ny prøving.`:''} ${x.reviewed?'Stasjonen er gjennomgått. Bruk også egne forklaringer.':'Svar på alle tre for å markere stasjonen som gjennomgått.'}`;}
function nextMarkup(id){const idx=STATIONS.findIndex(x=>x.id===id),prev=STATIONS[idx-1],next=STATIONS[idx+1];return `<div class="page-next"><a class="secondary" href="#${prev.id}">← ${esc(prev.nav)}</a><span class="completion" id="completion-${id}">${completed(id)?'✓ Gjennomgått':''}</span><a class="primary" href="#${next.id}">${esc(next.nav)} →</a></div>`;}
function renderWords(){main.innerHTML=`${pageHeading('STASJON 1 · SPRÅK OG FAG','Ordene åpner historien.','Trykk på et ord. Les forklaringen og eksemplet. Bruk så ordet i din egen setning.',false)}<label class="filter-label" for="word-search">Finn et fagord</label><input class="word-search" type="search" id="word-search" placeholder="Søk etter et ord eller en forklaring …"><div class="vocab-grid" id="vocab-grid">${wordCards(WORDS)}</div><p class="fine">Snakk sammen: Finn et tilsvarende ord på et annet språk du kan. Betyr det akkurat det samme? Lag en setning om historien.</p>${quizMarkup('ord',getQuiz('ord'))}${writing('ord','Velg tre fagord. Forklar dem med egne ord, og bruk ett av dem i en setning om historie.','Ordet … betyr … Et eksempel er …','En allianse er et samarbeid mellom land. En konsekvens er en følge av noe. Propaganda er budskap som skal påvirke holdninger. Under den kalde krigen brukte begge supermaktene propaganda.')}${nextMarkup('ord')}`;}
function wordCards(rows){return rows.length?rows.map(w=>{const i=WORDS.findIndex(x=>x[0]===w[0]);return `<details class="word"><summary>${esc(w[0])}</summary><p>${esc(w[1])}<span class="example">${esc(w[2])}</span></p>${w[0]==='folkemord'?'<details class="word-precision"><summary>Mer presist</summary><p>Begrepet gjelder nasjonale, etniske, rasemessige og religiøse grupper. Det kreves hensikt om å ødelegge gruppen helt eller delvis.</p></details>':''}<div class="word-language"><label for="word-note-${i}">Mitt språk / egne ord</label><input id="word-note-${i}" data-word="${esc(w[0])}" value="${esc(state.wordNotes[w[0]]||'')}" dir="auto" maxlength="500" placeholder="Skriv et ord eller en forklaring …"><small id="word-save-${i}">Lagres i denne nettleseren.</small></div></details>`;}).join(''):'<p class="empty">Ingen treff. Prøv et annet ord.</p>'; }
function todayActivity(){return `<div class="activity"><h3>1. Uenighet, vold og forebygging</h3><p>Fredelig politisk uenighet og støtte til vold er ulike ting. Undersøk handlinger i tekstene. Du skal ikke sette merkelapper på klassekamerater eller andre du kjenner.</p><div class="source-cards"><div class="source-card"><h3>Fredelig deltakelse</h3><p>En gruppe kritiserer regjeringen. Gruppen lager en underskriftskampanje og demonstrerer fredelig.</p></div><div class="source-card"><h3>Støtte til vold</h3><p>Et nettmiljø sprer fiendebilder. Noen begynner å si at vold mot en gruppe er nødvendig.</p></div></div><ol><li>Hva er forskjellen på handlingene?</li><li>Velg to mulige forebyggende tiltak: tilhørighet, møte hat med motargumenter, samtale med en trygg voksen eller kunnskap om rettigheter.</li><li>Forklar hvordan tiltakene kan hjelpe. Hvorfor virker ikke ett tiltak likt for alle?</li></ol><p class="fine">Dette er tenkte eksempler, ikke en metode for å diagnostisere enkeltpersoner. Bruk «kan bidra til», og undersøk flere årsaker.</p></div><div class="activity"><h3>2. Et datert vedtak og kilder fra vår tid</h3><span class="label">FN · 2. MARS 2022 · BEARBEIDET SAMMENDRAG</span><p>FNs generalforsamling vedtok resolusjon ES-11/1. Den fordømte Russlands aggresjon mot Ukraina og krevde russisk tilbaketrekking. Vedtaket tok også opp følger for sivile. Dette er et kort sammendrag, ikke et ordrett sitat.</p><p>${external(SOURCES.ukraina,'Åpne vedtaket og arkivopplysningene')}</p><p class="callout">Kilden viser et vedtak fra 2022. Den er ikke en oppdatering om krigen i dag. En krig mellom stater og et terrorangrep må undersøkes som ulike fenomener.</p><p>Læreren velger to daterte artikler om en nåtidig konflikt. Bruk gjerne ulike avsendere. Sammenlign dokumentasjon, formål og hva kildene velger å ta med.</p>${sourceField('a')}${sourceField('b')}<ol><li>Finn én opplysning med dokumentasjon.</li><li>Finn én vurdering eller påstand. Hvordan begrunnes den?</li><li>Hva framhever hver avsender? Hva er utelatt?</li><li>Skriv ett spørsmål kildene ikke gir svar på.</li></ol><p class="fine">Du trenger ikke fortelle om egne erfaringer. Avtal et annet datert eller historisk case med læreren hvis du trenger det.</p></div>`;}
function sourceField(letter){const id=`idag-source-${letter}`;return `<div class="source-field"><label for="answer-${id}">Kilde ${letter.toUpperCase()}: avsender, dato og tittel eller lenke</label><input id="answer-${id}" data-answer="${id}" aria-describedby="save-${id}" placeholder="Avsender · dato · tittel/lenke"><small id="save-${id}" class="save-status">Lagres i denne nettleseren.</small></div>`;}
function activity(type){if(TOPIC.activities?.[type])return TOPIC.activities[type]();switch(type){
 case 'today':return todayActivity();
 case 'causes':return `<div class="activity"><h3>Hva kom før – og hva kom etter?</h3><p>Sorter forklaringene på første verdenskrig. Velg en kategori for hver setning.</p>${[['Stormaktene konkurrerte om kolonier.','a'],['Tronfølgeren ble drept i Sarajevo i 1914.','u'],['Flere keiserriker brøt sammen.','k'],['Land bygde stadig sterkere militærstyrker.','a']].map((r,i)=>`<div class="sort-row"><label for="sort-${i}">${r[0]}</label><select id="sort-${i}" data-sort-answer="${r[1]}"><option value="">Velg kategori</option><option value="a">Langsiktig årsak</option><option value="u">Utløsende hendelse</option><option value="k">Konsekvens</option></select></div>`).join('')}<button class="secondary" id="check-sort">Sjekk sorteringen</button><div id="sort-feedback" class="feedback" role="status"></div></div>`;
 case 'timeline':return `<div class="activity"><h3>Se hendelsene i sammenheng</h3><p>Velg et årstall. Hva er en årsak, og hva er en følge av noe som skjedde tidligere?</p><div class="activity-buttons">${EVENTS.map((e,i)=>`<button data-full-event="${i}" aria-pressed="${i===0}">${e.year}</button>`).join('')}</div><div class="reveal-box" id="full-event" aria-live="polite"><strong>${EVENTS[0].title}</strong><p>${EVENTS[0].text}</p></div><details class="more"><summary>Se hele tidslinjen samtidig</summary><div class="full-events">${EVENTS.map(e=>`<div><b>${e.year}</b>${e.title}</div>`).join('')}</div></details></div>`;
 case 'ideology':return `<div class="activity"><h3>Ideer og styresett</h3><p>Velg et begrep. Skill mellom ideene og hvordan en stat faktisk blir styrt.</p><div class="activity-buttons">${['Liberalt demokrati','Fascisme','Nazisme','Kommunisme'].map((x,i)=>`<button data-ideology="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><div class="reveal-box" id="ideology-info" aria-live="polite">${ideologyText(0)}</div><p class="fine">Samtalespørsmål: Hvilke rettigheter trenger en politisk motstander for å kunne delta i et demokrati?</p></div>`;
 case 'sequence':return `<div class="activity"><h3>Hva skjedde først?</h3><p>Flytt hendelsene med pilene. Sett den tidligste øverst. Du trenger ikke dra med musen.</p><ol class="sequence-list" id="sequence"></ol><button class="secondary" id="check-sequence">Sjekk rekkefølgen</button><div class="feedback" id="sequence-feedback" role="status"></div></div>`;
 case 'rights':return `<div class="activity"><h3>Se hvordan rettigheter ble brutt ned</h3><p>Velg en del av utviklingen i Nazi-Tyskland. Dette er en historisk oversikt, ingen automatisk eller uunngåelig trapp.</p><div class="activity-buttons">${['Fiendebilder','Tap av rettigheter','Systematiske massedrap','Forebygging'].map((x,i)=>`<button data-rights="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><div class="reveal-box" id="rights-info" aria-live="polite">${rightsText(0)}</div><p class="fine">Du skal ikke spille gjerningsperson eller offer. Undersøk handlingene, ansvaret og følgene.</p></div>`;
 case 'coldcompare':return `<div class="activity"><h3>Økonomi, styresett og allianser</h3><div class="table-scroll"><table class="comparison"><caption class="fine">Forenklet sammenligning av hovedtrekk under den kalde krigen.</caption><thead><tr><th>Spørsmål</th><th>USA</th><th>Sovjetunionen</th></tr></thead><tbody><tr><th>Økonomi</th><td>Kapitalisme, private bedrifter og markeder. Staten hadde også en viktig rolle.</td><td>Statlig eierskap og planøkonomi.</td></tr><tr><th>Styresett</th><td>Flerpartivalg og demokratiske institusjoner. Blant annet raseskille begrenset like rettigheter.</td><td>Ettpartistyre, sensur og undertrykking av politisk opposisjon.</td></tr><tr><th>Militærallianse</th><td>NATO fra 1949.</td><td>Warszawapakten fra 1955.</td></tr></tbody></table></div><p class="callout">Mange land tilhørte ingen av militæralliansene. Land i Asia, Afrika og Latin-Amerika hadde egne interesser, og avkolonisering endret verden.</p><p>Snakk sammen: Hvorfor kan ikke «kapitalisme» og «demokrati» brukes som ord for akkurat det samme?</p></div>`;
 case 'berlin':return `<div class="activity"><h3>Berlin: En by inne i et delt land</h3><svg class="diagram" viewBox="0 0 700 300" role="img" aria-labelledby="berlin-title berlin-desc"><title id="berlin-title">Forenklet skisse av Vest-Tyskland, Øst-Tyskland og det delte Berlin etter 1949.</title><desc id="berlin-desc">Vest-Berlin lå inne i Øst-Tyskland. Berlin var delt i en vestlig og en østlig del. Skissen viser ikke virkelige landegrenser eller målestokk.</desc><rect x="10" y="20" width="270" height="235" rx="16" fill="var(--soft)" stroke="var(--accent)"/><rect x="300" y="20" width="390" height="235" rx="16" fill="var(--warm)" stroke="var(--rust)"/><text x="145" y="65" text-anchor="middle" fill="currentColor" font-size="20" font-weight="bold">Vest-Tyskland</text><text x="495" y="65" text-anchor="middle" fill="currentColor" font-size="20" font-weight="bold">Øst-Tyskland (DDR)</text><rect x="415" y="110" width="75" height="85" rx="4" fill="var(--soft)" stroke="var(--accent)"/><rect x="490" y="110" width="75" height="85" rx="4" fill="var(--surface)" stroke="var(--rust)"/><text x="452" y="143" text-anchor="middle" fill="currentColor" font-size="13">Vest-</text><text x="452" y="164" text-anchor="middle" fill="currentColor" font-size="13">Berlin</text><text x="528" y="143" text-anchor="middle" fill="currentColor" font-size="13">Øst-</text><text x="528" y="164" text-anchor="middle" fill="currentColor" font-size="13">Berlin</text><path d="M210 153 H405" stroke="var(--accent)" stroke-dasharray="7 5" stroke-width="2"/><text x="145" y="225" text-anchor="middle" fill="currentColor" font-size="13">Vestlig orientert</text><text x="495" y="225" text-anchor="middle" fill="currentColor" font-size="13">Under sovjetisk dominans</text><text x="350" y="286" text-anchor="middle" fill="var(--muted)" font-size="13">Pedagogisk skisse · Ikke et geografisk kart · Ikke målestokk</text></svg><h3>Samme mur, ulike beskrivelser</h3><p>Pedagogiske forklaringer av ståsteder. Dette er ikke historiske sitater.</p><div class="activity-buttons">${['DDR-regimets framstilling','En familie som blir skilt','Undersøk handlingen'].map((x,i)=>`<button data-perspective="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><div class="reveal-box" id="perspective-info" aria-live="polite">${perspectiveText(0)}</div></div>`;
 case 'sources':return `<div class="activity"><h3>To kilder – to begrunnelser</h3><p>Begge tekstene nedenfor er korte, forenklede gjengivelser på norsk. De er ikke ordrette sitater. Følg lenkene for å se originalene.</p><div class="source-cards"><article class="source-card"><span class="label">KILDE A · TALE · 1947</span><h3>USAs president Harry S. Truman</h3><small>Til Kongressen, 12. mars 1947. Ber om støtte til Hellas og Tyrkia.</small><p>Truman sier at USA bør støtte frie folk som møter tvang fra væpnede mindretall eller press utenfra. Han framstiller amerikansk hjelp som et forsvar for frihet.</p>${external(SOURCES.truman,'Les originalkilden hos National Archives')}</article><article class="source-card"><span class="label">KILDE B · TRAKTAT · 1955</span><h3>Statene i Warszawapakten</h3><small>Traktatens innledning, 14. mai 1955. Avtale under sovjetisk ledelse.</small><p>Traktaten framstiller vesttysk opprustning og tilknytning til NATO som en trussel mot freden. Medlemsstatene begrunner sitt samarbeid med behovet for å verne egen sikkerhet.</p>${external(SOURCES.warsaw,'Les originalkilden i Avalon Project')}</article></div><p class="callout">Kildene er fra ulike år og svarer ikke direkte på hverandre. Sammenlign hvordan de begrunner politikk, og undersøk den ulike sammenhengen.</p><details class="more"><summary>Fire spørsmål til kildene</summary><ol><li>Hvem er avsender, og hvem skal påvirkes?</li><li>Hvordan beskrives egen side og en mulig motstander?</li><li>Hva kan teksten vise om avsenderens budskap?</li><li>Hvilke andre kilder trenger vi for å undersøke faktiske handlinger?</li></ol></details><h3>Illustrasjon eller historisk kilde?</h3><p>Et fotoekte utseende viser ikke sikkert hvem som laget et bilde. Bildeinformasjon og opphav må undersøkes.</p><p>Sammenlign KI-illustrasjonen med arkivfotoet nedenfor. Undersøk også kildelenkene og bildeopplysningene.</p>${imageComparison()}<ol><li>Hvem har laget og publisert hvert bilde?</li><li>Hvilken dato, fotograf eller arkivinformasjon finner du?</li><li>Hva kan illustrasjonen hjelpe deg å forstå? Hva kan den ikke dokumentere?</li><li>Hvilken historisk informasjon kan arkivbildet gi? Hva trenger du fortsatt andre kilder til?</li></ol><h3>Hva om algoritmen bare viser ett syn?</h3><p>Du ser fem videoer som alle gjentar samme påstand. Hva undersøker du først?</p><div class="activity-buttons"><button data-feed="repeat">Se flere videoer som sier det samme</button><button data-feed="trace">Finn opphavet og sammenlign uavhengige kilder</button></div><div class="feedback" id="feed-feedback" role="status"></div></div>`;
 case 'peace':return `<div class="activity"><h3>Hva slags samarbeid er dette?</h3><p>Velg et dokument eller en organisasjon. Finn formålet, og spør hva den kan og ikke kan gjøre.</p><div class="activity-buttons">${['FN-pakten · 1945','Menneskerettigheter · 1948','NATO · 1949'].map((x,i)=>`<button data-peace="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><div class="reveal-box" id="peace-info" aria-live="polite">${peaceText(0)}</div><p class="fine">Snakk sammen: Hvorfor kan et land skrive under en avtale og likevel bryte den? Hva må til for at avtalen får virkning?</p></div>`;
 default:return '';
}}
function ideologyText(i){if(easy())return ["<strong>Demokrati med rettigheter</strong><p>Folk kan velge mellom partier. Opposisjonen kan kritisere regjeringen. Også mindretallet har rettigheter. Flertallet kan ikke bestemme alt.</p>", "<strong>Fascisme</strong><p>Ideologien avviser demokrati. En sterk leder skal bestemme. Lydighet, nasjonalisme og maktbruk står sentralt. Mussolinis Italia er et eksempel.</p>", "<strong>Nazisme</strong><p>Nazismen ville ha diktatur og erobring. Rasisme og hat mot jøder sto sentralt. Nazistene brukte fiendebilder til å begrunne overgrep.</p>", "<strong>Kommunisme: idé og praksis</strong><p>Kommunistisk teori har et samfunn uten klasser som mål. I Sovjetunionen styrte ett parti alene. Staten planla økonomien. Vi må skille ideer fra det myndighetene faktisk gjorde.</p>"][i];return [
 '<strong>Liberalt demokrati</strong><p>Frie og reelle valg, politisk konkurranse, rettsstat og grunnleggende rettigheter. Flertallet kan bestemme mye, men skal ikke fritt ta rettigheter fra et mindretall.</p>',
 '<strong>Fascisme</strong><p>En autoritær og sterkt nasjonalistisk ideologi som avviser liberalt demokrati. En sterk leder, lydighet og maktbruk står sentralt. Mussolinis Italia er et historisk eksempel.</p>',
 '<strong>Nazisme</strong><p>En tysk variant av fascismen med raseideologi og antisemittisme i sentrum. Nazistene ville ha diktatur og erobring. Fiendebilder ble brukt til å begrunne forfølgelse og folkemord.</p>',
 '<strong>Kommunisme: idé og sovjetisk praksis</strong><p>Kommunistisk teori har et klasseløst samfunn og felles eierskap som mål. I Sovjetunionen utviklet det seg et ettpartidiktatur med planøkonomi og omfattende undertrykking. En ideologis mål og statens praksis må undersøkes hver for seg.</p>'
 ][i];}
function rightsText(i){if(easy())return ["<strong>Fiendebilder</strong><p>Nazistene spredte falske påstander om jøder. Jøder ble framstilt som en fiende. Dette kunne gjøre det lettere å få støtte til overgrep.</p>", "<strong>Tap av rettigheter</strong><p>Jøder ble stengt ute fra arbeid og utdanning. Staten brukte lover og politi i forfølgelsen.</p>", "<strong>Organiserte drap</strong><p>Nazistene og deres medhjelpere organiserte massedrap under krigen. Mennesker tok beslutninger og deltok. De hadde ansvar.</p>", "<strong>Vern av mennesker</strong><p>Domstoler og rettigheter kan beskytte minoriteter. Kunnskap og motstand mot hat kan også hjelpe. Reglene må følges i praksis.</p>"][i];return [
 '<strong>Fiendebilder og antisemittisme</strong><p>Nazistene spredte falske forestillinger om jøder som en farlig fiende. Avhumanisering betyr å framstille mennesker som mindre verdt. Det kunne gjøre det lettere å få støtte til overgrep.</p>',
 '<strong>Utestenging og tap av rettigheter</strong><p>Jøder ble utestengt fra arbeid, utdanning og fellesskap. Lover og statsapparat ble brukt i forfølgelsen. Vold og diskriminering ble en del av myndighetenes politikk.</p>',
 '<strong>Organisert folkemord</strong><p>Under krigen gjennomførte nazistene og deres medhjelpere systematiske massedrap. Det krevde beslutninger, organisering og deltakelse. Ofrene hadde ulik bakgrunn, ulike liv og ulike former for motstand.</p>',
 '<strong>Hva kan beskytte mennesker?</strong><p>Uavhengige domstoler, reelt minoritetsvern, kunnskap og motstand mot hat kan motvirke overgrep. Spør også hvem som har ansvar for at rettighetene blir fulgt i praksis.</p>'
 ][i];}
function perspectiveText(i){if(easy())return ["<strong>Regimets budskap</strong><p>DDR-regimet sa at muren beskyttet landet mot fiender fra vest. Dette var regimets framstilling. Vi må også undersøke det myndighetene gjorde.</p>", "<strong>En familie blir skilt</strong><p>En familie kunne miste kontakt med hverandre. De kunne ikke reise fritt. Dette viser en følge for menneskene.</p>", "<strong>Hva kan vi undersøke?</strong><p>Muren hindret mennesker i å forlate DDR. Vi kan undersøke regler, bilder og vitnesbyrd. Ulike beskrivelser gjør ikke alle påstander like godt dokumentert.</p>"][i];return [
 '<strong>Et forsvar i regimets egen fortelling</strong><p>DDR-regimet framstilte muren som beskyttelse mot fiender fra vest. Slik kunne en begrensning av innbyggernes frihet presenteres som et forsvarstiltak.</p>',
 '<strong>Et inngrep i hverdagen</strong><p>En familie på hver sin side kunne oppleve muren som tap av frihet og kontakt. Menneskers erfaringer kan vise konsekvenser som et offisielt budskap nedtoner.</p>',
 '<strong>Hva kan vi dokumentere?</strong><p>Muren og grensevaktene hindret mennesker i å reise fra DDR. Dette kan undersøkes gjennom lover, grenseordrer, bilder, fluktforsøk og vitnesbyrd. Ulike perspektiver opphever ikke dokumenterbare hendelser.</p>'
 ][i];}
function peaceText(i){if(easy())return ["<strong>FN-pakten</strong><p>Dette er en bindende avtale mellom land. Den beskriver blant annet arbeid for fred og menneskerettigheter. Uenighet mellom land kan hindre felles tiltak.</p>", "<strong>Menneskerettighetserklæringen</strong><p>FN vedtok den i 1948. Den sier at alle har samme verdi og grunnleggende rettigheter. Den er ikke i seg selv en bindende avtale. Senere avtaler gir land konkrete plikter.</p>", "<strong>NATO</strong><p>NATO er en militær forsvarsallianse. Den ble opprettet i 1949. Norge var med fra starten. Alliansen kan hindre angrep, men også øke andres frykt.</p>"][i];return [
 '<strong>FN-pakten: en internasjonal traktat</strong><p>Grunnlaget for FN. Formålene omfatter internasjonal fred og sikkerhet, samarbeid og menneskerettigheter. Statene har forpliktelser, men motsetninger mellom dem kan hindre felles tiltak.</p>',
 '<strong>Verdenserklæringen: et felles ideal</strong><p>Vedtatt av FN i 1948. Alle mennesker har samme menneskeverd og grunnleggende rettigheter. Erklæringen er ikke i seg selv en bindende traktat. Senere konvensjoner gir konkrete rettslige forpliktelser.</p>',
 '<strong>NATO: en militær forsvarsallianse</strong><p>Opprettet i 1949 med Norge som medlem fra starten. Felles forsvar skal avskrekke angrep. En allianse kan samtidig oppfattes som en trussel av andre stater. Vi må undersøke både formål og faktisk politikk.</p>'
 ][i];}
let sequence=[2,1,4,3,0];
const sequenceItems=[{year:1933,text:'Hitler blir utnevnt til rikskansler'},{year:1939,text:'Tyskland angriper Polen'},{year:1940,text:'Norge blir angrepet 9. april'},{year:1941,text:'Tyskland angriper Sovjetunionen'},{year:1945,text:'Tyskland kapitulerer'}];
function renderSequence(){document.querySelector('#sequence').innerHTML=sequence.map((id,i)=>`<li><span>${esc(sequenceItems[id].text)}</span><button data-move="${i}" data-dir="-1" aria-label="Flytt ${esc(sequenceItems[id].text)} opp" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-dir="1" aria-label="Flytt ${esc(sequenceItems[id].text)} ned" ${i===sequence.length-1?'disabled':''}>↓</button></li>`).join('');}
function renderFinal(){main.innerHTML=`${pageHeading('AVSLUTNING · BRUK DET DU HAR LÆRT','Vis sammenhengene.','Lag en kort fagtekst eller forbered en muntlig forklaring. Du skal bruke kunnskap, eksempler og kilder sammen.',false)}<div class="activity task-select"><label for="final-topic"><strong>Velg en konflikt eller periode</strong></label><select id="final-topic">${['Første verdenskrig','Andre verdenskrig','Den kalde krigen','Cubakrisen'].map(t=>`<option ${state.finalTopic===t?'selected':''}>${t}</option>`).join('')}</select><p id="final-prompt">${finalPrompt()}</p><ol><li>Plasser konflikten i tid, og si hvem som deltok.</li><li>Forklar minst to årsaker og én konsekvens.</li><li>Vis ett perspektiv: Hva framhevet en bestemt aktør, og hvorfor?</li><li>Bruk to kilder. Oppgi avsender og tittel eller lenke. Si hva én av dem kan brukes til, og en begrensning.</li><li>Vurder ett tiltak som kunne dempe konflikten eller forebygge nye overgrep.</li></ol><p class="fine">Omfang avtales med læreren. Du kan bruke en kort tekst med tydelige avsnitt eller stikkord til en muntlig presentasjon.</p></div>${writing('slutt','Min fagtekst eller mine presentasjonsnotater','Konflikten jeg undersøker, er … Den fant sted … En viktig årsak var … Dette bidro fordi … En annen årsak … En konsekvens … Fra … sitt perspektiv … Kilden … viser … Samtidig kan den ikke alene … Et mulig tiltak er …','En god forklaring kobler årsaker til det som skjedde: «Kapprustning kunne øke frykten fordi hvert land oppfattet den andres nye våpen som en trussel. Dette kunne gjøre det vanskeligere å stole på løfter om fred.» Bruk egne eksempler og oppgi kildene dine.')}<section class="goals checklist"><h2>Før jeg leverer</h2>${[['tid','Jeg har plassert hendelsene i tid.'],['aarsaker','Jeg har forklart hvordan årsaker kunne virke.'],['perspektiv','Jeg har vist et perspektiv uten å ta alle påstander for gitt.'],['kilder','Jeg har oppgitt og vurdert kilder.'],['fagord','Jeg har brukt fagord og et konkret eksempel.']].map(([id,text])=>`<label><input type="checkbox" data-self="${id}" ${state.checks[id]?'checked':''}>${text}</label>`).join('')}</section><h2>Slik kan du utvikle svaret</h2><div class="rubric"><div><h3>Beskriv</h3>Hvem, hva og når? Bruk relevante fagord og korrekte opplysninger.</div><div><h3>Forklar</h3>Hvordan og hvorfor? Vis årsakssammenhenger og konkrete konsekvenser.</div><div><h3>Vurder</h3>Se flere perspektiver. Undersøk kilder og begrunn vurderingen din.</div></div><p class="fine">Dette er arbeidsstøtte, ikke en automatisk karaktervurdering. Læreren vurderer faglig forståelse, kildebruk og forklaringer.</p><button class="primary" data-open-notes>Se og last ned svarene mine ↓</button><div class="page-next"><a class="secondary" href="#idag">← Konflikt i dag</a><a href="#laerer">Kilder og informasjon →</a></div>`;}
function finalPrompt(){return `Du har valgt <strong>${esc(state.finalTopic)}</strong>. Bruk punktene under til å bygge svaret.`;}
function renderTeacher(){main.innerHTML=`${pageHeading('LÆRERROMMET','Et løp om konflikt og fred.','Historiske konflikter, vold og kildearbeid i vår tid. Fleksibel bruk i par, klasse eller alene.',false)}
<section class="teacher-section"><h2>Faglig og språklig retning</h2><p>Lett vei er skrevet med korte setninger, forklarte fagord og oppdelt tekst. Den retter seg mot elever som trenger støtte rundt A2. Vanlig vei gir mer sammenheng og nyanser rundt B1. Dette er pedagogiske tilpasninger, ikke formelt vurderte språknivåer. Elevene kan trenge forkunnskaper, høytlesing og lærerstøtte på begge veier.</p><p>Begge veier arbeider med samme faglige kjerne: årsak → valg og handling → konsekvens → perspektiv → kildevurdering. Alle kontrollspørsmål har egne språkversjoner med samme faglige innhold. Ordbanken forklarer både grunnord og sentrale ord fra teksten. «Mitt språk / egne ord» lagres lokalt og følger med i nedlastede svar.</p></section>
<section class="teacher-section"><h2>Læreplankobling</h2><p>${external(SOURCES.udir)}. Dette er korte bearbeidinger av deler av målene.</p><div class="table-scroll"><table class="comparison"><thead><tr><th>Kompetanse</th><th>Arbeid i løpet</th></tr></thead><tbody><tr><td>Historiske og nåtidige konflikter, årsaker og perspektiver</td><td>Verdenskrigene, den kalde krigen og «Konflikt i dag». Daterte nyhetskilder velges sammen med læreren.</td></tr><tr><td>Kilders formål, relevans, algoritmer og ensidighet</td><td>Kildeverkstedet, bildeoppgaven og et datert FN-vedtak.</td></tr><tr><td>Radikalisering, terror, folkemord og forebygging</td><td>Holocaust, 22. juli, radikalisering mot vold og forebyggende handlinger.</td></tr><tr><td>Avtaler, rettigheter og plikter</td><td>FN-pakten, Warszawapakten og skillet mellom erklæring og traktat.</td></tr><tr><td>Skriftlig og muntlig faglig forklaring</td><td>Samtalespørsmål, egne forklaringer, kildearbeid og sluttoppgave.</td></tr></tbody></table></div><p>Dette temaet dekker deler av modul 4. På fellesforsiden finner du også «Rikdom, fattigdom og levekår». Norsk styresett, mer om økonomi og arbeidsliv og andre kompetansemål trenger egne læringsløp. En kort stasjon om vår tid gir en inngang til kompetansemålene, ikke uttømmende dekning.</p></section>
<section class="teacher-section"><h2>Trygg og traumesensitiv gjennomføring</h2><p>Varsle om tema og innhold på forhånd. Bruk offentlige kilder og tenkte eksempler; ikke be elever fortelle om egen krig, flukt eller tap. Ingen skal måtte representere et land, en religion eller en folkegruppe. Unngå grafiske bilder og rollespill som offer eller gjerningsperson.</p><p>Gi mulighet for pause, en roligere arbeidsplass eller en alternativ oppgave uten krav om å begrunne det foran gruppen. Avtal et annet historisk case hvis et eksempel blir for nært. Behold faglig arbeid med årsak, konsekvens og kilder. Ved behov følger læreren skolens vanlige rutiner for støtte og oppfølging.</p><p>Snakk tydelig om forskjellen mellom stater, myndigheter og enkeltmennesker. Undersøk påstander med dokumentasjon. Å gi rom for ulike erfaringer innebærer ikke å behandle alle historiske eller faktiske påstander som like godt begrunnet.</p></section>
<section class="teacher-section"><h2>Vurdering og framgang</h2><p>Løpet har ${learningIds().length} fagstasjoner, i tillegg til start og avslutning. Tre besvarte spørsmål markerer en fagstasjon som «gjennomgått», også når eleven har feil. Det betyr utført øving, ikke mestring.</p><p>Første registrerte svar lagres for hvert spørsmål. Nye forsøk endrer ikke dette resultatet. Riktig etter ny prøving vises separat. Feiltilbakemeldingen gjelder det valgte alternativet og peker mot videre arbeid. Full forklaring vises etter riktig svar. Eleven kan bruke teksten og få hjelp fra starten: dette er øving, ikke en uavhengig prøve eller en karakter.</p><p>Bruk muntlige og skriftlige forklaringer, eksempler og kildevurdering for å undersøke samlet kompetanse. Et riktig kryss alene viser ikke at eleven kan forklare. Etter denne revisjonen starter quizregistreringen på nytt; tidligere tekstsvar beholdes.</p></section>
<section class="teacher-section"><h2>Arbeidsmåte og praktisk bruk</h2><ol><li>Start med ord og årsak/konsekvens. Bruk elevenes språkressurser frivillig.</li><li>Arbeid med én periode om gangen. Bruk tidslinjen for å knytte hendelser sammen.</li><li>La par forklare før de skriver. Elevene kan også arbeide alene.</li><li>Gjør kildeverkstedet sammen første gang. Åpne originalkilder og skill mellom kilde og bearbeiding.</li><li>Velg to daterte, tilgjengelige artikler til «Konflikt i dag». Kontroller at ordvalg, bilder og innhold passer elevgruppen. FN-caset fra 2022 er ikke en oppdatering om dagens situasjon.</li></ol><p>Svar, ordnotater og quizresultater lagres i nettleseren på enheten. Det finnes ingen automatisk lærerinnboks. Bruk «Mine svar» for nedlasting eller utskrift. Ved delt enhet: ta vare på arbeidet før dere bruker «Begynn på nytt».</p><p>Opplesing bruker enhetens innebygde talefunksjon. Tilgjengelig norsk stemme avhenger av nettleser og enhet. Utskrift viser lagrede skriftlige svar, ordnotater og øvingsresultater.</p></section>
<section class="teacher-section"><h2>Bilder og historiske kilder</h2><p>Siden bruker tre arkivfotografier: Somme i juli 1916, byggingen av Berlinmuren i august 1961 og et flyfoto fra Cuba tatt 14. oktober 1962. Bildetekstene oppgir fotograf eller institusjon, arkivnummer, kilde og bruksvilkår. Arkivfotoene vises med hele utsnittet fra kildefilen; forsidekortet viser et tilpasset utsnitt.</p><p>Fire godkjente KI-illustrasjoner viser tenkte situasjoner. De er merket og skal ikke brukes som dokumentasjon på hendelsene. I kildeverkstedet vises illustrasjonen av fototolkere sammen med det faktiske flyfotoet fra Cuba. Elevene undersøker opphav, formål og hva hvert bilde kan dokumentere. Utseendet alene avgjør ikke et bildes opphav.</p><p>Arkivfotografier kan brukes til å undersøke fotograf, formål og historisk sammenheng. Somme-bildet og Cuba-fotoet er oppført som public domain. Berlin-bildet brukes under CC BY-SA 3.0 DE, med kreditering og lisenslenke ved bildet. Tekster fra NATO, PST og amerikanske myndigheter har institusjonelle ståsteder; de brukes med oppmerksomhet på formål og dokumentasjon. De to kalde-krigen-kildene er merkede sammendrag, ikke oppdiktede sitater.</p><p>Tidslinjen har et norsk ankerpunkt for holocaust: Donau-deportasjonen 26. november 1942. Fagtekster og kilder er gjennomgått 5. november 2026.</p><ul class="teacher-links">${Object.values(SOURCES).map(x=>`<li>${external(x)}<span>${esc(x.note)}</span></li>`).join('')}</ul></section><a class="primary" href="#start">Til læringsløpet →</a>`;}

function restoreNotes(){document.querySelectorAll('[data-answer]').forEach(t=>t.value=state.answers[t.dataset.answer]||'');}
function stopSpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel();const b=document.querySelector('#stop-speech');if(b)b.hidden=true;}
function speak(){const t=document.querySelector('#reading-text');if(!t)return;if(!('speechSynthesis'in window)){toast('Opplesing er ikke tilgjengelig i denne nettleseren.');return;}stopSpeech();const utterance=new SpeechSynthesisUtterance(t.innerText);utterance.lang='nb-NO';utterance.rate=.88;const voices=window.speechSynthesis.getVoices();const v=voices.find(x=>/^(nb|no|nn)/i.test(x.lang));if(v)utterance.voice=v;utterance.onend=()=>{const b=document.querySelector('#stop-speech');if(b)b.hidden=true;};utterance.onerror=()=>{stopSpeech();toast('Opplesingen kunne ikke starte. Prøv en annen nettleser eller les sammen.');};document.querySelector('#stop-speech').hidden=false;window.speechSynthesis.speak(utterance);}
function answerRows(){
 const extra=TOPIC.extraAnswers||[{id:'idag-source-a',title:'Konflikt i dag · Kilde A'},{id:'idag-source-b',title:'Konflikt i dag · Kilde B'}];
 const rows=[{id:'ord',title:'Ord'},...LESSONS.map(x=>({id:x.id,title:x.title})),{id:'slutt',title:`Sluttoppgave · ${state.finalTopic}`},...extra].filter(x=>state.answers[x.id]?.trim()).map(x=>({...x,text:state.answers[x.id]}));
 const languages=Object.entries(state.wordNotes).filter(([,v])=>v.trim()).map(([word,v])=>`${word}: ${v}`).join('\n');
 if(languages)rows.unshift({id:'wordnotes',title:'Min ordbank · Mitt språk / egne ord',text:languages});
 return rows;
}
function resultsText(){return learningIds().filter(id=>questionSummary(id).attempted).map(id=>`${id==='ord'?'Ordbank':LESSONS.find(l=>l.id===id).title}: ${quizSummary(id)}`).join('\n');}
function showNotes(){const rows=answerRows(),results=resultsText();document.querySelector('#saved-answers').innerHTML=(results?`<section><h3>Kontrollspørsmål · øving</h3><p>${esc(results)}</p></section>`:'')+(rows.length?rows.map(x=>`<section><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></section>`).join(''):'<p class="empty">Du har ikke skrevet noen svar ennå. Ordnotatene dine kommer også her.</p>');if(!dialog.open)dialog.showModal();}
function exportText(){const rows=answerRows(),ids=learningIds(),done=ids.filter(completed).length;return [`FORSTÅ VERDEN · ${(TOPIC.title||'Konflikt og fred').toLocaleUpperCase('nb')}`,'Samfunnsfag FOV modul 4',`Gjennomgått: ${done} av ${ids.length} fagstasjoner. Dette er øving, ikke en karakter.`,resultsText(),`Valgt sluttoppgave: ${state.finalTopic}`,'',...rows.flatMap(x=>[x.title.toUpperCase(),x.text,''])].join('\n');}
function download(){const blob=new Blob(['\uFEFF'+exportText()],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=TOPIC.downloadName||'Mine_svar_konflikt_og_fred.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function preparePrint(){document.querySelector('#print-area').innerHTML=`<h1>${esc(TOPIC.title||'Konflikt og fred')}</h1><p class="fine">Samfunnsfag FOV modul 4 · Mine svar<br>Navn: ____________________ &nbsp; Dato: ____________________</p>${resultsText()?`<section><h2>Kontrollspørsmål · øving</h2><p>${esc(resultsText())}</p></section>`:''}${answerRows().map(x=>`<section><h2>${esc(x.title)}</h2><p>${esc(x.text)}</p></section>`).join('')||'<p>Ingen svar er skrevet ennå.</p>'}`;}
function printNotes(){preparePrint();window.print();}
function feedback(id,text,correct=true){const el=document.getElementById(id);el.textContent=text;el.className=`feedback ${correct?'correct':'wrong'}`;}
function setPressed(selector,target){document.querySelectorAll(selector).forEach(x=>x.setAttribute('aria-pressed',String(x===target)));}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(TOPIC.onClick?.(b))return;
 if(b.dataset.level){const y=window.scrollY;state.level=b.dataset.level;save();stopSpeech();render();window.scrollTo({top:y,behavior:'instant'});return;}
 if(b.dataset.event!==undefined){const item=EVENTS[Number(b.dataset.event)];setPressed('[data-event]',b);document.querySelector('#hero-event').innerHTML=`<strong>${item.title}</strong><p>${item.text}</p>`;return;}
 if(b.dataset.fullEvent!==undefined){const item=EVENTS[Number(b.dataset.fullEvent)];setPressed('[data-full-event]',b);document.querySelector('#full-event').innerHTML=`<strong>${item.year} · ${item.title}</strong><p>${item.text}</p><a href="#${item.id}">Les kapitlet →</a>`;return;}
 for(const [key,selector,destination,fn]of [['ideology','[data-ideology]','ideology-info',ideologyText],['rights','[data-rights]','rights-info',rightsText],['perspective','[data-perspective]','perspective-info',perspectiveText],['peace','[data-peace]','peace-info',peaceText]]){if(b.dataset[key]!==undefined){setPressed(selector,b);document.getElementById(destination).innerHTML=fn(Number(b.dataset[key]));return;}}
 if(b.dataset.check){
 const id=b.dataset.check,i=Number(b.dataset.index),field=document.getElementById(`question-${id}-${i}`),selected=field.querySelector('input:checked');
 if(!selected){field.querySelector('.feedback').textContent='Velg et svar først.';return;}
 const q=getQuiz(id)[i],key=`${id}-${i}`,previous=state.quiz[key],choice=Number(selected.value);
 if(previous?.attempts&&previous.selected===choice&&!previous.correct){field.querySelector('.feedback').textContent='Velg et annet svar før du sjekker igjen. Du kan lese teksten først.';return;}
 const r=LearningState.attempt(previous,choice,q.correct);state.quiz[key]=r;save();
 field.querySelector('.feedback').innerHTML=questionFeedback(q,r);field.querySelector('.feedback').className=`feedback ${r.correct?'correct':'wrong'}`;
 field.querySelector('.attempt-status').textContent=`Første svar: ${r.firstCorrect?'riktig':'ikke riktig'}. Antall forsøk: ${r.attempts}.`;
 if(r.correct){field.querySelectorAll('input').forEach(x=>x.disabled=true);b.disabled=true;b.textContent='Riktig ✓';}
 document.getElementById(`quiz-summary-${id}`).textContent=quizSummary(id);updateHeader();document.getElementById(`completion-${id}`).textContent=completed(id)?'✓ Gjennomgått':'';return;
 }
 if(b.dataset.move!==undefined){const idx=Number(b.dataset.move),next=idx+Number(b.dataset.dir);if(next>=0&&next<sequence.length){[sequence[idx],sequence[next]]=[sequence[next],sequence[idx]];renderSequence();document.querySelector('#sequence-feedback').textContent='';document.querySelector(`[data-move="${next}"][data-dir="${b.dataset.dir}"]`)?.focus();}return;}
 if(b.dataset.feed){feedback('feed-feedback',b.dataset.feed==='trace'?'Ja. Finn den opprinnelige påstanden og undersøk om uavhengige kilder støtter den. Flere kopier er ikke flere bekreftelser.':'Flere lignende videoer kan gjenta den samme feilen. Undersøk opphavet og kilder som er uavhengige av hverandre.',b.dataset.feed==='trace');setPressed('[data-feed]',b);return;}
 if(b.id==='check-sort'){const rows=[...document.querySelectorAll('[data-sort-answer]')];if(rows.some(x=>!x.value)){feedback('sort-feedback','Velg en kategori for alle fire setningene.',false);return;}const n=rows.filter(x=>x.value===x.dataset.sortAnswer).length;feedback('sort-feedback',n===4?'Alle fire er riktige. Konkurranse om kolonier og opprustning kom før krisen. Attentatet utløste krisen. Keiserrikenes sammenbrudd var en følge.':`${n} av 4 riktige. Tenk: Hva skapte spenning over tid? Hva utløste krisen? Hva kom som en følge?`,n===4);return;}
 if(b.id==='check-sequence'){const correct=sequence.every((id,i)=>id===i);feedback('sequence-feedback',correct?'Riktig rekkefølge: 1933 → 1939 → 1940 → 1941 → 1945. Forklar en sammenheng mellom to av hendelsene.':'Se på tidslinjen og teksten. Start med Hitlers utnevnelse. Prøv igjen.',correct);return;}
 if(b.id==='theme'){state.theme=state.theme==='dark'?'light':'dark';save();updateHeader();return;}
 if(b.id==='open-notes'||b.hasAttribute('data-open-notes')){showNotes();return;}
 if(b.id==='close-notes'){dialog.close();return;}
 if(b.id==='download'){download();return;}
 if(b.id==='print-notes'){printNotes();return;}
 if(b.id==='speak'){speak();return;}
 if(b.id==='stop-speech'){stopSpeech();return;}
 if(b.id==='reset'){state={...blankState(),level:state.level,theme:state.theme};save();dialog.close();sequence=[2,1,4,3,0];render();toast('Svar og framgang er nullstilt på denne enheten.');return;}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-word]')){const word=e.target.dataset.word;state.wordNotes[word]=e.target.value;const ok=save(),i=WORDS.findIndex(w=>w[0]===word);document.getElementById(`word-save-${i}`).textContent=ok?'Lagret.':'Kan ikke lagre. Last ned notatene før du lukker siden.';}if(e.target.matches('[data-answer]')){state.answers[e.target.dataset.answer]=e.target.value;const ok=save();document.getElementById(`save-${e.target.dataset.answer}`).textContent=ok?'Svaret er lagret i denne nettleseren.':'Kan ikke lagre her. Åpne «Mine svar» og last ned svaret.';}if(e.target.id==='word-search'){const q=e.target.value.trim().toLocaleLowerCase('nb');document.querySelector('#vocab-grid').innerHTML=wordCards(WORDS.filter(w=>(w.join(' ')+' '+(state.wordNotes[w[0]]||'')).toLocaleLowerCase('nb').includes(q)));}});
document.addEventListener('change',e=>{if(TOPIC.onChange?.(e.target))return;if(e.target.matches('[data-self]')){state.checks[e.target.dataset.self]=e.target.checked;save();}if(e.target.id==='final-topic'){state.finalTopic=e.target.value;save();document.getElementById('final-prompt').innerHTML=finalPrompt();}});
